// minerpg: the parts of the origins redesign (pack 1.6.0) that NeoOrigins data can't express.
// Design: docs/superpowers/specs/2026-11-05-minerpg-origins-redesign.md. The origins and powers themselves are
// generated by pack/tools/gen_origins.py.
//
// - Vein Miner (Deepkin): sneaking while breaking an ore breaks the whole connected vein, up to 32 blocks. Each
//   block is broken as if the player mined it (claims, tool durability, Fortune, job XP all apply). NeoOrigins'
//   own ultimine power only unlocks FTB Ultimine, which the pack doesn't have.
// - Searing Strikes (Emberkin) and Chilling Strikes (Rimeborn): a hit on a creature (melee or the player's own
//   projectile) sets it alight for 3 s / slows it for 2 s. Never on players: PvP is on and friends get hit by accident.
// - Feign Death (Gravebound): every mob within 32 blocks that was targeting the player forgets them.
// - One free Orb of Origin per player who already had an origin before the redesign, so they can switch.

const $OrResourceLocation = Java.loadClass('net.minecraft.resources.ResourceLocation')
const $OrTagKey = Java.loadClass('net.minecraft.tags.TagKey')
const $OrRegistries = Java.loadClass('net.minecraft.core.registries.Registries')
const $OrBlockPos = Java.loadClass('net.minecraft.core.BlockPos')
const $OrNeoOriginsAPI = Java.loadClass('com.cyberday1.neoorigins.api.NeoOriginsAPI')
const $OrMob = Java.loadClass('net.minecraft.world.entity.Mob')
const $OrStats = Java.loadClass('net.minecraft.stats.Stats')
const $OrComponent = Java.loadClass('net.minecraft.network.chat.Component')
const $OrFormat = Java.loadClass('net.minecraft.ChatFormatting')
const $OrCallbacks = Java.loadClass('com.cyberday1.neoorigins.compat.kubejs.KubeJSCallbacks')
const $OrDamagePost = Java.loadClass('net.neoforged.neoforge.event.entity.living.LivingDamageEvent$Post')
const $OrPlayer = Java.loadClass('net.minecraft.world.entity.player.Player')
const $OrServerPlayer = Java.loadClass('net.minecraft.server.level.ServerPlayer')
const $OrEffectInstance = Java.loadClass('net.minecraft.world.effect.MobEffectInstance')
const $OrEffects = Java.loadClass('net.minecraft.world.effect.MobEffects')

const OR_VEIN_POWER = 'minerpg:deepkin_vein_miner'
const OR_ORES = $OrTagKey.create($OrRegistries.BLOCK, $OrResourceLocation.parse('c:ores'))
const OR_VEIN_MAX = 32
const OR_FEIGN_RADIUS = 32
const OR_SEARING_POWER = 'minerpg:emberkin_searing_strikes'
const OR_CHILLING_POWER = 'minerpg:rimeborn_chilling_strikes'
const OR_ORB_FLAG = 'minerpg_origins_redesign_orb'
// Players with less play time than this are new: they pick their origin on the join screen anyway.
const OR_NEW_PLAYER_TICKS = 10 * 60 * 20

function orHasPower(player, id) {
  var found = false
  $OrNeoOriginsAPI.powers(player).forEach(holder => {
    if (String(holder.id()) == id) found = true
  })
  return found
}

// The connected blocks of the same kind as the one at start (26-neighbourhood), nearest first, start excluded.
function orVein(level, start, block) {
  var seen = {}
  seen[start.asLong()] = true
  var queue = [start]
  var found = []
  while (queue.length > 0 && found.length < OR_VEIN_MAX) {
    var pos = queue.shift()
    for (var dx = -1; dx <= 1; dx++) {
      for (var dy = -1; dy <= 1; dy++) {
        for (var dz = -1; dz <= 1; dz++) {
          var next = pos.offset(dx, dy, dz)
          var key = next.asLong()
          if (seen[key]) continue
          seen[key] = true
          if (level.getBlockState(next).getBlock() != block) continue
          if (found.length >= OR_VEIN_MAX) return found
          found.push(next)
          queue.push(next)
        }
      }
    }
  }
  return found
}

var orVeinMining = false

BlockEvents.broken(event => {
  var player = event.player
  if (orVeinMining || player == null || !player.isShiftKeyDown()) return
  var state = event.block.blockState
  // is() is overloaded (tag / block / holder ...); Rhino needs the one named.
  if (!state['is(net.minecraft.tags.TagKey)'](OR_ORES) || !orHasPower(player, OR_VEIN_POWER)) return
  var level = event.level
  var start = event.block.pos
  var vein = orVein(level, start, state.getBlock())
  if (vein.length == 0) return
  // A tick later, once the first block is gone. destroyBlock fires every check a normal break would.
  event.server.scheduleInTicks(1, () => {
    orVeinMining = true
    try {
      for (var i = 0; i < vein.length; i++) {
        var tool = player.getMainHandItem()
        // Stop before the tool's last point of durability so the vein never breaks a tool.
        if (tool.isDamageableItem() && tool.getMaxDamage() - tool.getDamageValue() <= 1) break
        if (!player.isAlive() || player.distanceToSqr(vein[i].getCenter()) > 64) break
        player.gameMode.destroyBlock(vein[i])
      }
    } finally {
      orVeinMining = false
    }
  })
})

NativeEvents.onEvent($OrDamagePost, event => {
  var victim = event.getEntity()
  if (victim instanceof $OrPlayer || event.getNewDamage() <= 0) return
  // KubeJS remaps DamageSource#getEntity to getActual(): the player behind a melee hit or their projectile.
  var attacker = event.getSource().getActual()
  if (!(attacker instanceof $OrServerPlayer)) return
  if (orHasPower(attacker, OR_SEARING_POWER)) victim.igniteForSeconds(3)
  if (orHasPower(attacker, OR_CHILLING_POWER)) victim.addEffect(new $OrEffectInstance($OrEffects.MOVEMENT_SLOWDOWN, 40, 0))
})

// Registered as kept: NeoOrigins clears server-script callbacks at the end of every data reload (after this script
// has run), so the plain NeoOrigins.registerCallback binding would leave the id empty.
$OrCallbacks.register('minerpg:feign_death', player => {
  var box = player.getBoundingBox().inflate(OR_FEIGN_RADIUS)
  player.serverLevel().getEntitiesOfClass($OrMob, box).forEach(mob => {
    if (mob.getTarget() == player) mob.setTarget(null)
  })
}, true)

PlayerEvents.loggedIn(event => {
  var player = event.player
  var data = player.persistentData
  if (data.getBoolean(OR_ORB_FLAG)) return
  data.putBoolean(OR_ORB_FLAG, true)
  var played = player.getStats().getValue($OrStats.CUSTOM.get($OrStats.PLAY_TIME))
  if (played < OR_NEW_PLAYER_TICKS) return
  player.give('neoorigins:orb_of_origin')
  player.tell($OrComponent.literal('The origins have changed: every folk is stronger, with a real drawback. '
    + 'Here is a free Orb of Origin if you want to choose again (the handbook has the new folk).').withStyle($OrFormat.GOLD))
})
